  panel.style.display = "none";
  if (Number.isFinite(Number(width))) panel.style.width = `${nextPanelWidth(width, 0)}px`;
  const publishWidth = (w) => root?.style?.setProperty?.("--pxd-panel-w", `${w}px`);
