      copy.type = "button";
      copy.setAttribute("data-act", "copy");
      const rename = el("button", "pxd-btn pxd-view-rename", row3, "Rename");
      rename.type = "button";
      rename.setAttribute("data-act", "rename");
      const del = el("button", "pxd-btn pxd-view-delete", row3, "Delete");
